from fastapi import FastAPI, Header, Request
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/")
async def read_root(x_token: str = Header(None)):
    return {"x_token": x_token}

client = TestClient(app)

def test_underscore_header_rejected_by_default():
    # By default convert_underscores=True. 
    # The request header 'x_token' should be ignored because it contains an underscore.
    # FastAPI should treat it as if the header was not provided.
    response = client.get("/", headers={"x_token": "foo"})
    assert response.status_code == 200
    assert response.json() == {"x_token": None}

def test_hyphen_header_accepted_by_default():
    # 'x-token' should be converted to 'x_token' and accepted.
    response = client.get("/", headers={"x-token": "foo"})
    assert response.status_code == 200
    assert response.json() == {"x_token": "foo"}

